<div class="flex flex-wrap gap-3 justify-between items-center mb-4"><form class="flex flex-wrap gap-2 items-center" method="get"><input class="input !w-56" name="q" value="<?= e($f['q']) ?>" placeholder="Search name or SKU"><select name="category" class="select !w-44"><option value="">All categories</option><?php foreach ($categories as $c): ?><option value="<?= (int)$c['id'] ?>" <?= (int)$f['cat'] === (int)$c['id'] ? 'selected' : '' ?>><?= e($c['name']) ?></option><?php endforeach; ?></select>
  <select name="status" class="select !w-36"><option value="">Active + inactive</option><?php foreach (['active', 'inactive', 'archived'] as $s): ?><option <?= $f['st'] === $s ? 'selected' : '' ?>><?= $s ?></option><?php endforeach; ?></select>
  <label class="flex items-center gap-1.5 text-sm"><input type="checkbox" name="stock" value="low" <?= $f['stock'] === 'low' ? 'checked' : '' ?>> Low stock</label><button class="btn btn-soft">Filter</button></form>
  <div class="flex flex-wrap gap-2"><a href="<?= e(url('/admin/products/import')) ?>" class="btn btn-soft"><?= icon('file-spreadsheet', 'w-4 h-4') ?> Excel import / export</a><a href="<?= e(url('/admin/products/create')) ?>" class="btn btn-primary"><?= icon('plus', 'w-4 h-4') ?> Add product</a></div></div>
<div class="card overflow-hidden"><div class="overflow-x-auto"><table class="table-x w-full text-sm"><thead><tr><th>Product</th><th>SKU</th><th>Category</th><th>Price</th><th>Stock</th><th>Status</th><th></th></tr></thead><tbody>
<?php foreach ($rows as $p): $low = $p['stock'] <= $p['low_stock_threshold']; ?><tr><td><div class="flex items-center gap-3"><span class="w-11 h-11 rounded-lg tint-accent overflow-hidden shrink-0"><?php if ($p['image']): ?><img src="<?= e(upload_url($p['image'])) ?>" class="w-full h-full object-cover" alt=""><?php endif; ?></span><a class="font-semibold hover:text-primary" href="<?= e(url('/admin/products/' . $p['id'])) ?>"><?= e($p['name']) ?></a></div></td>
<td class="font-mono"><?= e($p['sku']) ?></td><td><?= e($p['category_name']) ?></td><td><b><?= money($p['selling_price']) ?></b><?php if ($p['discount_percent'] > 0): ?> <s class="text-xs muted"><?= money($p['original_price']) ?></s><?php endif; ?></td>
<td><span class="badge <?= $p['stock'] <= 0 ? 'bg-red-100 text-red-700' : ($low ? 'bg-amber-100 text-amber-800' : 'bg-green-100 text-green-700') ?>"><?= (int)$p['stock'] ?><?= $low && $p['stock'] > 0 ? ' · low' : '' ?></span></td>
<td><span class="badge <?= $p['status'] === 'active' ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-600' ?>"><?= e($p['status']) ?></span></td>
<td class="whitespace-nowrap text-right"><a class="btn btn-soft btn-sm" href="<?= e(url('/admin/products/' . $p['id'] . '/edit')) ?>">Edit</a>
<?php if ($p['status'] === 'archived'): ?><form class="inline" method="post" action="<?= e(url('/admin/products/' . $p['id'] . '/restore')) ?>"><?= csrf_field() ?><button class="btn btn-outline btn-sm">Restore</button></form>
<?php else: ?><form class="inline" method="post" action="<?= e(url('/admin/products/' . $p['id'] . '/archive')) ?>"><?= csrf_field() ?><button class="btn btn-outline btn-sm" data-confirm="Archive this product? It will be hidden from customers.">Archive</button></form><?php endif; ?>
<form class="inline" method="post" action="<?= e(url('/admin/products/' . $p['id'] . '/delete')) ?>"><?= csrf_field() ?><button class="btn btn-danger btn-sm" data-confirm="Delete this product permanently? (Products with orders are archived instead.)">Delete</button></form></td></tr>
<?php endforeach; if (!$rows): ?><tr><td colspan="7" class="text-center muted py-12">No products found.</td></tr><?php endif; ?></tbody></table></div></div>
